import type * as NodeCryptoModule from "node:crypto";
// Baseline snapshots generated by actual 0d73f895 handlers, same emulator fixture. Fixed Date/doc IDs/UUID only. See live comparison evidence.
import { describe, it, expect, vi } from "vitest";
import { getFirestore } from "firebase-admin/firestore";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { resolve, join } from "node:path";
import { tmpdir } from "node:os";
import { initiatePayment } from "../../functions/payment/initiatePayment.js";
import { recordManualPayment } from "../../functions/payment/recordManualPayment.js";
import { advanceJobStatus } from "../../functions/job/advanceJobStatus.js";
vi.mock("node:crypto", async (importOriginal) => ({
  ...(await importOriginal<typeof NodeCryptoModule>()),
  randomUUID: () => "00000000-0000-4000-8000-000000000001",
}));
const db = getFirestore(),
  id = "fx-noncovered-zero",
  cols = [
    "jobs",
    "bookings",
    "payments",
    "invoices",
    "auditLog",
    "invoiceCounters",
    "warranties",
    "services",
    "customers",
  ];
const auth = {
  uid: "staff",
  token: { role: "admin", tenantId: "zero-control", studioId: null },
};
async function seed(delivery: boolean, error: boolean) {
  // Hard guard (same rule as 57fd6f67): this cleanup is destructive, so it
  // may only ever run against an emulator backend - a fake tenant name is
  // not safety proof.
  if (!process.env["FIRESTORE_EMULATOR_HOST"]) {
    throw new Error("noncovered-zero seed cleanup requires FIRESTORE_EMULATOR_HOST; refusing to clean up against a non-emulator backend.");
  }
  // vehicles and rateLimits are cleaned but NOT compared: the delivery case
  // seeds a live vehicle for the protection-declaration guard, and rate-limit
  // buckets are stamped with the fake fixed Date, so without cleanup they
  // accumulate across runs into the same never-sliding window and every
  // later run is permanently exhausted. Neither may leak into the vehicle-
  // free baseline conditions. (Rate-limit docs carry no tenantId field; the
  // tenant is the doc-id prefix.)
  for (const c of [...cols, "vehicles"]) {
    const q = await db.collection(c).where("tenantId", "==", "zero-control").get();
    for (const d of q.docs) await d.ref.delete();
  }
  const rl = await db.collection("rateLimits").get();
  for (const d of rl.docs) if (d.id.startsWith("zero-control__")) await d.ref.delete();
  await db.collection("invoiceCounters").doc("zero-control_2026").delete();
  const now = new Date().toISOString(),
    pb = {
      vehicleCategory: "hatchback",
      basePrice: 0,
      scopeAdjustment: 0,
      addOns: [],
      subtotal: 0,
      membershipDiscount: 0,
      membershipDiscountPercent: null,
      pickupFee: 0,
      dropFee: 0,
      taxRatePercent: 0,
      taxDescription: "No tax",
      tax: 0,
      total: 0,
      currency: "INR",
    };
  await db
    .collection("jobs")
    .doc(id)
    .set({
      id,
      tenantId: "zero-control",
      studioId: "s",
      customerId: "c",
      vehicleId: "v",
      serviceId: id,
      bookingId: null,
      status: error ? "CANCELLED" : delivery ? "READY_FOR_DELIVERY" : "PENDING_VEHICLE",
      paymentStatus: delivery ? "paid" : "unpaid",
      priceBreakdown: pb,
      totalAmount: 0,
      additionalWorkDelta: 0,
      statusHistory: [],
      isWalkIn: true,
      createdAt: now,
      updatedAt: now,
    });
  await db
    .collection("services")
    .doc(id)
    .set({ id, tenantId: "zero-control", name: "Zero ordinary service" });
  if (delivery) {
    // The DELIVERED path now verifies the car's live record before recording
    // the (possibly empty) protection-work declaration: seed a matching
    // vehicle owned by the job's customer.
    await db.collection("vehicles").doc("v").set({
      id: "v",
      tenantId: "zero-control",
      ownerId: "c",
      registrationNumber: "GJ01ZZ0000",
      make: "Test",
      model: "Car",
      year: 2024,
      color: "White",
      photoUrl: null,
      createdAt: now,
      updatedAt: now,
    });
    await db.collection("invoices").doc("fx-zero-existing").set({
      id: "fx-zero-existing",
      jobId: id,
      tenantId: "zero-control",
      status: "paid",
      total: 0,
    });
  }
}
async function capture(fn: any, kind: string, error: boolean) {
  const delivery = kind === "delivery";
  await seed(delivery, error);
  const counters: Record<string, number> = {};
  const proto = Object.getPrototypeOf(db.collection("jobs")),
    orig = proto.doc,
    spy = vi.spyOn(proto, "doc").mockImplementation(function (
      this: { path: string },
      ...args: unknown[]
    ) {
      return args.length
        ? orig.apply(this, args)
        : orig.call(this, "fx-zero-auto-" + (counters[this.path] = (counters[this.path] || 0) + 1));
    });
  try {
    let outcome;
    try {
      outcome = {
        result: await fn.run({
          data: {
            jobId: id,
            // The DELIVERED transition now (0a493cf8/2f79a469, reviewed)
            // requires an explicit protection-work declaration; this fixture
            // job has none, so the honest declaration is the empty list.
            ...(delivery ? { protectionWork: [] } : { method: kind === "cash" ? "cash" : "razorpay_payment_link" }),
          },
          auth,
        } as never),
      };
    } catch (e: any) {
      outcome = { error: { code: e.code, message: e.message } };
    }
    const docs: Record<string, unknown> = {};
    for (const c of cols) {
      const q = await db.collection(c).where("tenantId", "==", "zero-control").get();
      docs[c] = q.docs
        .map((d) => ({ id: d.id, data: d.data() }))
        .sort((a, b) => a.id.localeCompare(b.id));
    }
    return { outcome, docs };
  } finally {
    spy.mockRestore();
  }
}
describe("noncovered zero functions baseline0d73f895 comparison", () => {
  for (const [kind, after] of [
    ["link", initiatePayment],
    ["cash", recordManualPayment],
    ["delivery", advanceJobStatus],
  ] as const)
    it(`${kind} same outputs writes and cancelled error as baseline`, async () => {
      vi.useFakeTimers({ toFake: ["Date"] });
      vi.setSystemTime(new Date("2026-10-24T09:00:00Z"));
      try {
        for (const error of [false, true]) {
          const b = JSON.parse(
              readFileSync(resolve(__dirname, "../fixtures/noncovered-zero-baseline.json"), "utf8"),
            )[kind + "-" + (error ? "error" : "success")],
            a = await capture(after, kind, error);
          // Evidence first: on a mismatch these files are the diagnosis.
          const evidenceDir = process.env["EVIDENCE_DIR"] ?? join(tmpdir(), "evidence");
          mkdirSync(evidenceDir, { recursive: true });
          writeFileSync(
            join(evidenceDir, `noncovered-zero-${kind}-${error ? "error" : "success"}-baseline.json`),
            JSON.stringify(b, null, 2),
          );
          writeFileSync(
            join(evidenceDir, `noncovered-zero-${kind}-${error ? "error" : "success"}-current.json`),
            JSON.stringify(a, null, 2),
          );
          expect(a).toEqual(b);
          console.log(
            "BASE VS CURRENT",
            kind,
            error ? "cancelled-error" : "success",
            JSON.stringify(a.outcome),
          );
        }
      } finally {
        vi.useRealTimers();
      }
    });
});
